export const catalog = [
 { id:'eufycam-s3-pro', name:'eufyCam S3 Pro', category:'Security camera', image:'assets/s3-pro.svg', url:'https://www.eufy.com/au/eufycam-pro', description:'Security camera with HomeBase 3. Open the illustrated camera preview or review viewer access.', kind:'camera' },
 { id:'omni-s1-pro', name:'Robot Vacuum Omni S1 Pro', category:'Robot vacuum & mop', image:'assets/omni-s1-pro.svg', url:'https://www.eufy.com/au/products/eufy-robot-vacuum-s1-pro', description:'S1 Pro (T2080) robot vacuum and mop with its docking station. The RGB camera is used for obstacle avoidance; this prototype does not provide a live vacuum camera feed.', kind:'vacuum' },
 { id:'video-doorbell-e340', name:'Video Doorbell E340', category:'Video doorbell', url:'https://www.eufy.com/au/video-doorbell-e340', description:'E340 (T8214) dual-camera video doorbell for the front door. Open its illustrated preview or review viewer access.', kind:'doorbell' }
];
const doorbellArtwork = `<svg viewBox="0 0 160 210" role="img" aria-label="Illustration of Video Doorbell E340"><ellipse cx="80" cy="194" rx="38" ry="7" fill="#dfe8f0"/><rect x="44" y="10" width="72" height="181" rx="23" fill="#192c39" stroke="#41515a" stroke-width="2"/><rect x="52" y="18" width="56" height="164" rx="18" fill="#243744"/><rect x="60" y="27" width="40" height="9" rx="4" fill="#dce8eb"/><circle cx="80" cy="60" r="22" fill="#14212d"/><circle cx="80" cy="60" r="14" fill="#35546b"/><circle cx="80" cy="60" r="9" fill="#091724"/><circle cx="84" cy="56" r="4" fill="#72a9cc"/><circle cx="80" cy="105" r="17" fill="#14212d"/><circle cx="80" cy="105" r="10" fill="#35546b"/><circle cx="80" cy="105" r="6" fill="#091724"/><circle cx="80" cy="153" r="15" fill="none" stroke="#00b8d4" stroke-width="3"/><text x="80" y="133" text-anchor="middle" font-family="Arial,sans-serif" font-size="8" fill="#abbcc7">eufy</text></svg>`;
const productArtwork = p => p.kind==='doorbell' ? doorbellArtwork : `<img src="${p.image}" alt="${p.name}" loading="lazy">`;
export function productThumbnail(id){const p=catalog.find(item=>item.id===id);return p?productArtwork(p):'';}
export function doorbellCard(){const p=catalog.find(item=>item.id==='video-doorbell-e340');return `<article class="device-card doorbell-device-card"><div class="device-card-heading"><div><h2>${p.name}</h2><p>Video doorbell <span>· Demo device</span></p></div><span class="badge">Front door · Demo</span></div><a class="doorbell-device-art" href="#product/${p.id}" aria-label="Open Video Doorbell E340 product">${productArtwork(p)}</a><div class="vacuum-footer"><span>Video Doorbell</span><a class="eufy-secondary" href="#product/${p.id}">View Product</a></div></article>`;}
export function homeProductCards(){return doorbellCard()+vacuumCard();}
export function productCards(){return `<section class="catalog-section"><div class="catalog-heading"><h2>Your selected products</h2><p>From your product references</p></div><div class="catalog-grid">${catalog.map(p=>`<article class="catalog-card"><a href="#product/${p.id}" class="catalog-image">${productArtwork(p)}</a><div class="catalog-copy"><p class="catalog-category">${p.category}</p><h3><a href="#product/${p.id}">${p.name}</a></h3>${p.price?`<strong class="catalog-price">${p.price}</strong><small>Reference price from supplied screenshot</small>`:'<small>See the official eufy page for current details.</small>'}<a class="eufy-primary" href="#product/${p.id}">View Product</a></div></article>`).join('')}</div></section>`;}
export function productView(app,id){const p=catalog.find(p=>p.id===id)||catalog[0];app.className='native-page product-page';document.title=`eufy · ${p.name}`;app.innerHTML=`<div class="page-heading"><a href="#home" aria-label="Back to Home">‹</a><h1>Product Details</h1></div><section class="product-detail"><div class="product-main-image">${productArtwork(p)}</div><div class="product-main-copy"><span class="catalog-category">${p.category}</span><h2>${p.name}</h2>${p.price?`<strong class="catalog-price">${p.price}</strong><p class="reference-price">Reference price from your screenshot · Not a live offer</p>`:'<p class="reference-price">Product reference · Check the official eufy page for current details.</p>'}<p class="product-description">${p.description}</p><div class="product-links">${p.kind==='camera'?'<a class="eufy-primary" href="#device/living-room">Open Camera</a><a class="eufy-secondary" href="#events/access">Access History</a>':p.kind==='vacuum'?'<span class="badge">Demo device · Docked</span>':'<a class="eufy-primary" href="#device/front-door">Open Doorbell</a><a class="eufy-secondary" href="#events/access">Access History</a>'}<a class="official-product" href="${p.url}" target="_blank" rel="noopener noreferrer">View official eufy product ↗</a></div></div></section>`;}
export function vacuumCard(){const p=catalog[1];return `<article class="device-card vacuum-card"><div class="device-card-heading"><div><h2>Omni S1 Pro</h2><p>Robot Vacuum & Mop <span>· Demo device</span></p></div><span class="badge">Docked · Demo</span></div><a class="vacuum-image" href="#product/omni-s1-pro" aria-label="Open Omni S1 Pro product"><img src="${p.image}" alt="Omni S1 Pro robot vacuum and docking station" loading="lazy"></a><div class="vacuum-footer"><span>Robot Vacuum & Mop</span><a class="eufy-secondary" href="#product/omni-s1-pro">View Product</a></div></article>`;}
